// <auto-generated-by-handoff>
// Layer 1 — Uomd.Combat: Bit-exact C# 5v5 tactical turn-based battle engine.
// Uses IEEE-754 double arithmetic, UomdStatMath.RoundHalfUp, and Mulberry32Rng (Uomd.Core)
// so client simulations and server /api/v1/battles/verify replays match identically.

using System;
using System.Collections.Generic;
using Uomd.Core;

namespace Uomd.Combat
{
    public sealed class BattleSimulator
    {
        public const double TurnGaugeThreshold = 1000.0;
        public const int MaxBattleTurns = 80;

        private readonly string _battleId;
        private readonly uint _seed;
        private readonly Mulberry32Rng _rng;
        private readonly List<CombatUnitState> _units = new List<CombatUnitState>();
        private readonly List<BreakableObjectiveState> _objectives = new List<BreakableObjectiveState>();
        private readonly List<PendingTelegraphState> _telegraphs = new List<PendingTelegraphState>();
        private readonly Queue<string> _ultimateQueue = new Queue<string>();
        private readonly List<BattleActionRecord> _actions = new List<BattleActionRecord>();
        private readonly List<BattleEventRecord> _events = new List<BattleEventRecord>();

        private int _turn;
        private int _seq;
        private bool _finished;
        private bool _victory;

        public string BattleId => _battleId;
        public uint Seed => _seed;
        public int CurrentTurn => _turn;
        public bool IsFinished => _finished;
        public bool IsVictory => _victory;
        public IReadOnlyList<CombatUnitState> Units => _units;
        public IReadOnlyList<BreakableObjectiveState> Objectives => _objectives;
        public IReadOnlyList<BattleActionRecord> Actions => _actions;
        public IReadOnlyList<BattleEventRecord> Events => _events;

        public BattleSimulator(
            string battleId,
            uint seed,
            IEnumerable<CombatUnitState> initialUnits,
            IEnumerable<BreakableObjectiveState> objectives = null)
        {
            _battleId = battleId ?? "battle_local";
            _seed = seed;
            _rng = new Mulberry32Rng(seed);

            if (initialUnits != null)
            {
                foreach (var u in initialUnits)
                {
                    _units.Add(u);
                }
            }

            if (objectives != null)
            {
                foreach (var obj in objectives)
                {
                    _objectives.Add(obj);
                }
            }

            EmitEvent("battle_start", "", "", "", (int)seed, false, "", "", _battleId);
        }

        public CombatUnitState AdvanceToNextActor()
        {
            if (_finished) return null;

            CheckBattleEnd();
            if (_finished) return null;

            // Drain queued ultimate interrupts first
            while (_ultimateQueue.Count > 0)
            {
                string ultUnitId = _ultimateQueue.Dequeue();
                var ultUnit = FindUnit(ultUnitId);
                if (ultUnit != null && ultUnit.alive && ultUnit.focus >= ultUnit.maxFocus && !HasControlBlock(ultUnit, "stun") && !HasControlBlock(ultUnit, "silence"))
                {
                    return ultUnit;
                }
            }

            // Advance turn gauges deterministically
            for (int safety = 0; safety < 256; safety++)
            {
                CombatUnitState ready = PickHighestReadyUnit();
                if (ready != null)
                {
                    ready.gauge -= TurnGaugeThreshold;
                    if (ready.gauge < 0.0) ready.gauge = 0.0;
                    return ready;
                }

                double minTicks = double.MaxValue;
                for (int i = 0; i < _units.Count; i++)
                {
                    var u = _units[i];
                    if (!u.alive) continue;
                    double effSpd = Math.Max(1.0, GetEffectiveSpeed(u));
                    double needed = Math.Max(0.0, TurnGaugeThreshold - u.gauge);
                    double ticks = needed / effSpd;
                    if (ticks < minTicks) minTicks = ticks;
                }

                if (minTicks == double.MaxValue) break;

                for (int i = 0; i < _units.Count; i++)
                {
                    var u = _units[i];
                    if (!u.alive) continue;
                    u.gauge += GetEffectiveSpeed(u) * minTicks;
                }
            }

            return null;
        }

        public void ExecuteTurn(CombatUnitState actor, BattleActionKind? requestedKind = null, string requestedTargetId = null)
        {
            if (_finished || actor == null || !actor.alive) return;

            _turn++;
            if (_turn > MaxBattleTurns)
            {
                _finished = true;
                _victory = false;
                EmitEvent("battle_end", "", "", "", 0, false, "", "", "turn_limit_reached");
                return;
            }

            // Process start-of-turn DoTs / HoTs
            ProcessTurnStartStatuses(actor);
            if (!actor.alive)
            {
                CheckBattleEnd();
                return;
            }

            if (HasControlBlock(actor, "stun"))
            {
                EmitEvent("stun_skip", actor.instanceId, actor.instanceId, "", 0, false, "stun", "", "stunned");
                TickCooldownsAndStatusesEnd(actor);
                CheckBattleEnd();
                return;
            }

            SkillSpec skill = SelectSkill(actor, requestedKind);
            List<CombatUnitState> targets = ResolveTargets(actor, skill, requestedTargetId);

            string primaryTargetId = targets.Count > 0 ? targets[0].instanceId : "";
            _actions.Add(new BattleActionRecord
            {
                turn = _turn,
                actorId = actor.instanceId,
                kind = skill.kind.ToString().ToLowerInvariant(),
                skillId = skill.id,
                targetId = primaryTargetId
            });

            if (skill.kind == BattleActionKind.Ultimate)
            {
                actor.focus = 0;
            }
            else if (skill.kind == BattleActionKind.Active)
            {
                actor.activeCooldownRemaining = Math.Max(1, skill.cooldown);
                GrantFocus(actor, 30);
            }
            else
            {
                GrantFocus(actor, 20);
            }

            EmitEvent("skill_cast", actor.instanceId, primaryTargetId, skill.id, 0, false, "", skill.vfxPresetId, skill.name);

            if (skill.targetsAllies)
            {
                for (int i = 0; i < targets.Count; i++)
                {
                    var ally = targets[i];
                    if (!ally.alive) continue;

                    if (skill.healRatio > 0.0)
                    {
                        int heal = Math.Max(1, UomdStatMath.RoundHalfUp(actor.maxHp * skill.healRatio));
                        ally.hp = Math.Min(ally.maxHp, ally.hp + heal);
                        EmitEvent("heal", actor.instanceId, ally.instanceId, skill.id, heal, false, "", skill.vfxPresetId, "");
                    }

                    if (skill.shieldRatio > 0.0)
                    {
                        int shield = Math.Max(1, UomdStatMath.RoundHalfUp(actor.maxHp * skill.shieldRatio));
                        ApplyStatus(actor, ally, "shield", skill.statusDuration > 0 ? skill.statusDuration : 2, skill.shieldRatio, shield);
                    }

                    if (!string.IsNullOrEmpty(skill.statusId) && skill.statusId != "shield")
                    {
                        ApplyStatus(actor, ally, skill.statusId, skill.statusDuration, skill.statusPotency, 0);
                    }
                }
            }
            else
            {
                int hits = Math.Max(1, skill.hitCount);
                for (int i = 0; i < targets.Count; i++)
                {
                    var target = targets[i];
                    if (!target.alive) continue;

                    for (int h = 0; h < hits; h++)
                    {
                        if (!target.alive) break;
                        ApplyDamageHit(actor, target, skill, hits);
                    }

                    if (target.alive && !string.IsNullOrEmpty(skill.statusId) && skill.statusChance > 0.0)
                    {
                        double effChance = skill.statusChance * (1.0 + actor.effectHit - target.effectRes);
                        effChance = Math.Max(0.10, Math.Min(1.0, effChance));
                        if (_rng.NextDouble() < effChance)
                        {
                            ApplyStatus(actor, target, skill.statusId, skill.statusDuration, skill.statusPotency, 0);
                        }
                    }
                }

                if (skill.breaksObjective && _objectives.Count > 0)
                {
                    DamageBreakableObjectives(actor, skill);
                }
            }

            TickCooldownsAndStatusesEnd(actor);
            CheckBattleEnd();
        }

        public BattleSimulationOutcome RunFullAutoSimulation()
        {
            while (!_finished && _turn < MaxBattleTurns)
            {
                var actor = AdvanceToNextActor();
                if (actor == null) break;
                ExecuteTurn(actor);
            }
            return BuildOutcome();
        }

        public BattleSimulationOutcome BuildOutcome()
        {
            int totalAllies = 0;
            int survivingAllies = 0;
            for (int i = 0; i < _units.Count; i++)
            {
                if (_units[i].side == BattleSide.Player)
                {
                    totalAllies++;
                    if (_units[i].alive) survivingAllies++;
                }
            }

            int stars = _victory
                ? UomdStatMath.ComputeVictoryStars(totalAllies, survivingAllies, _turn, 15)
                : 0;

            var canonicalPayload = new SortedDictionary<string, object>(StringComparer.Ordinal)
            {
                ["battleId"] = _battleId,
                ["seed"] = (long)_seed,
                ["turnsTaken"] = _turn,
                ["victory"] = _victory,
                ["stars"] = stars,
                ["eventCount"] = _events.Count
            };

            return new BattleSimulationOutcome
            {
                battleId = _battleId,
                seed = _seed,
                victory = _victory,
                stars = stars,
                turnsTaken = _turn,
                totalAllies = totalAllies,
                survivingAllies = survivingAllies,
                actions = new List<BattleActionRecord>(_actions),
                events = new List<BattleEventRecord>(_events),
                logHash = CanonicalJson.Sha256Hash(canonicalPayload)
            };
        }

        private void ApplyDamageHit(CombatUnitState attacker, CombatUnitState defender, SkillSpec skill, int hitCount)
        {
            double effAtk = GetEffectiveAtk(attacker);
            double effDef = GetEffectiveDef(defender);
            double defMitigation = 1000.0 / (1000.0 + Math.Max(0.0, effDef));
            double perHitMult = skill.damageMultiplier / Math.Max(1, hitCount);
            double raw = effAtk * perHitMult * defMitigation;

            if (HasStatus(defender, "vuln"))
            {
                raw *= 1.20;
            }

            bool isCrit = _rng.NextDouble() < Math.Max(0.0, Math.Min(1.0, attacker.critRate));
            if (isCrit)
            {
                raw *= Math.Max(1.25, attacker.critDmg);
            }

            int dmg = Math.Max(1, UomdStatMath.RoundHalfUp(raw));
            int absorbed = AbsorbWithShield(defender, dmg);
            int hpDmg = Math.Max(0, dmg - absorbed);

            defender.hp = Math.Max(0, defender.hp - hpDmg);
            GrantFocus(defender, 10);

            EmitEvent("damage", attacker.instanceId, defender.instanceId, skill.id, dmg, isCrit, "", skill.vfxPresetId, absorbed > 0 ? $"shield_absorbed:{absorbed}" : "");

            if (defender.hp <= 0)
            {
                if (defender.bossPhase < defender.maxBossPhases)
                {
                    defender.bossPhase++;
                    defender.hp = defender.maxHp;
                    defender.statuses.Clear();
                    EmitEvent("boss_phase", defender.instanceId, defender.instanceId, "", defender.bossPhase, false, "", "", $"phase_{defender.bossPhase}");
                }
                else
                {
                    defender.alive = false;
                    defender.gauge = 0.0;
                    EmitEvent("unit_defeat", attacker.instanceId, defender.instanceId, skill.id, 0, false, "", "", "");
                }
            }
        }

        private void DamageBreakableObjectives(CombatUnitState actor, SkillSpec skill)
        {
            for (int i = 0; i < _objectives.Count; i++)
            {
                var obj = _objectives[i];
                if (obj.broken) continue;

                int dmg = Math.Max(1, UomdStatMath.RoundHalfUp(actor.atk * skill.damageMultiplier));
                obj.hp = Math.Max(0, obj.hp - dmg);
                EmitEvent("objective_hit", actor.instanceId, obj.id, skill.id, dmg, false, "", skill.vfxPresetId, obj.name);

                if (obj.hp <= 0)
                {
                    obj.broken = true;
                    EmitEvent("objective_break", actor.instanceId, obj.id, skill.id, obj.rewardFocus, false, "", "", obj.name);
                    for (int u = 0; u < _units.Count; u++)
                    {
                        if (_units[u].alive && _units[u].side == BattleSide.Player)
                        {
                            GrantFocus(_units[u], obj.rewardFocus);
                        }
                    }
                }
            }
        }

        private SkillSpec SelectSkill(CombatUnitState actor, BattleActionKind? requestedKind)
        {
            bool silenced = HasControlBlock(actor, "silence");

            if (requestedKind == BattleActionKind.Ultimate && !silenced && actor.focus >= actor.maxFocus && actor.ultimateSkill != null)
            {
                return actor.ultimateSkill;
            }
            if (requestedKind == BattleActionKind.Active && !silenced && actor.activeCooldownRemaining <= 0 && actor.activeSkill != null)
            {
                return actor.activeSkill;
            }

            if ( requestedKind == null )
            {
                if (!silenced && actor.focus >= actor.maxFocus && actor.ultimateSkill != null)
                {
                    return actor.ultimateSkill;
                }
                if (!silenced && actor.activeCooldownRemaining <= 0 && actor.activeSkill != null)
                {
                    return actor.activeSkill;
                }
            }

            return actor.basicSkill;
        }

        private List<CombatUnitState> ResolveTargets(CombatUnitState actor, SkillSpec skill, string requestedTargetId)
        {
            var list = new List<CombatUnitState>();
            BattleSide desiredSide = skill.targetsAllies ? actor.side : (actor.side == BattleSide.Player ? BattleSide.Enemy : BattleSide.Player);

            if (skill.isAoe)
            {
                for (int i = 0; i < _units.Count; i++)
                {
                    var u = _units[i];
                    if (u.alive && u.side == desiredSide)
                    {
                        list.Add(u);
                    }
                }
                return list;
            }

            // Check Taunt on opposing team
            if (!skill.targetsAllies)
            {
                for (int i = 0; i < _units.Count; i++)
                {
                    var u = _units[i];
                    if (u.alive && u.side == desiredSide && HasStatus(u, "taunt"))
                    {
                        list.Add(u);
                        return list;
                    }
                }
            }

            if (!string.IsNullOrEmpty(requestedTargetId))
            {
                var explicitTarget = FindUnit(requestedTargetId);
                if (explicitTarget != null && explicitTarget.alive && explicitTarget.side == desiredSide)
                {
                    list.Add(explicitTarget);
                    return list;
                }
            }

            // Deterministic default: front-most lowest-slot or lowest HP ratio
            CombatUnitState chosen = null;
            for (int i = 0; i < _units.Count; i++)
            {
                var u = _units[i];
                if (!u.alive || u.side != desiredSide) continue;
                if (chosen == null || u.slot < chosen.slot)
                {
                    chosen = u;
                }
            }

            if (chosen != null) list.Add(chosen);
            return list;
        }

        private void ProcessTurnStartStatuses(CombatUnitState actor)
        {
            for (int i = actor.statuses.Count - 1; i >= 0; i--)
            {
                var st = actor.statuses[i];
                if (st.id == "bleed" || st.id == "burn" || st.id == "poison")
                {
                    int dot = Math.Max(1, UomdStatMath.RoundHalfUp(actor.maxHp * Math.Max(0.05, st.potency) * st.stacks));
                    actor.hp = Math.Max(0, actor.hp - dot);
                    EmitEvent("status_dot", st.sourceId, actor.instanceId, "", dot, false, st.id, "", "");
                    if (actor.hp <= 0)
                    {
                        actor.alive = false;
                        EmitEvent("unit_defeat", st.sourceId, actor.instanceId, "", 0, false, st.id, "", "");
                        return;
                    }
                }
                else if (st.id == "regen")
                {
                    int hot = Math.Max(1, UomdStatMath.RoundHalfUp(actor.maxHp * Math.Max(0.06, st.potency)));
                    actor.hp = Math.Min(actor.maxHp, actor.hp + hot);
                    EmitEvent("status_hot", st.sourceId, actor.instanceId, "", hot, false, st.id, "", "");
                }
            }
        }

        private void TickCooldownsAndStatusesEnd(CombatUnitState actor)
        {
            if (actor.activeCooldownRemaining > 0)
            {
                actor.activeCooldownRemaining--;
            }

            for (int i = actor.statuses.Count - 1; i >= 0; i--)
            {
                actor.statuses[i].remainingTurns--;
                if (actor.statuses[i].remainingTurns <= 0)
                {
                    actor.statuses.RemoveAt(i);
                }
            }
        }

        private void ApplyStatus(CombatUnitState source, CombatUnitState target, string statusId, int duration, double potency, int shieldHp)
        {
            for (int i = 0; i < target.statuses.Count; i++)
            {
                if (target.statuses[i].id == statusId)
                {
                    target.statuses[i].remainingTurns = Math.Max(target.statuses[i].remainingTurns, duration);
                    target.statuses[i].stacks = Math.Min(5, target.statuses[i].stacks + 1);
                    target.statuses[i].shieldHp = Math.Max(target.statuses[i].shieldHp, shieldHp);
                    EmitEvent("status_apply", source.instanceId, target.instanceId, "", shieldHp, false, statusId, "", "refresh");
                    return;
                }
            }

            target.statuses.Add(new StatusInstance
            {
                id = statusId,
                remainingTurns = Math.Max(1, duration),
                stacks = 1,
                potency = potency,
                sourceId = source.instanceId,
                shieldHp = shieldHp
            });
            EmitEvent("status_apply", source.instanceId, target.instanceId, "", shieldHp, false, statusId, "", "new");
        }

        private int AbsorbWithShield(CombatUnitState defender, int incomingDamage)
        {
            int remaining = incomingDamage;
            for (int i = defender.statuses.Count - 1; i >= 0 && remaining > 0; i--)
            {
                var st = defender.statuses[i];
                if (st.id == "shield" && st.shieldHp > 0)
                {
                    int take = Math.Min(st.shieldHp, remaining);
                    st.shieldHp -= take;
                    remaining -= take;
                    if (st.shieldHp <= 0)
                    {
                        defender.statuses.RemoveAt(i);
                    }
                }
            }
            return incomingDamage - remaining;
        }

        private void GrantFocus(CombatUnitState unit, int delta)
        {
            if (!unit.alive) return;
            int before = unit.focus;
            unit.focus = Math.Min(unit.maxFocus, unit.focus + delta);
            if (before < unit.maxFocus && unit.focus >= unit.maxFocus)
            {
                _ultimateQueue.Enqueue(unit.instanceId);
            }
        }

        private CombatUnitState PickHighestReadyUnit()
        {
            CombatUnitState best = null;
            for (int i = 0; i < _units.Count; i++)
            {
                var u = _units[i];
                if (!u.alive || u.gauge < TurnGaugeThreshold) continue;
                if (best == null
                    || u.gauge > best.gauge
                    || (Math.Abs(u.gauge - best.gauge) < 1e-9 && u.spd > best.spd)
                    || (Math.Abs(u.gauge - best.gauge) < 1e-9 && u.spd == best.spd && string.CompareOrdinal(u.instanceId, best.instanceId) < 0))
                {
                    best = u;
                }
            }
            return best;
        }

        private void CheckBattleEnd()
        {
            bool anyPlayerAlive = false;
            bool anyEnemyAlive = false;
            for (int i = 0; i < _units.Count; i++)
            {
                if (!_units[i].alive) continue;
                if (_units[i].side == BattleSide.Player) anyPlayerAlive = true;
                else anyEnemyAlive = true;
            }

            if (!anyEnemyAlive || !anyPlayerAlive)
            {
                _finished = true;
                _victory = anyPlayerAlive && !anyEnemyAlive;
                EmitEvent("battle_end", "", "", "", _victory ? 1 : 0, false, "", "", _victory ? "victory" : "defeat");
            }
        }

        private CombatUnitState FindUnit(string instanceId)
        {
            for (int i = 0; i < _units.Count; i++)
            {
                if (_units[i].instanceId == instanceId) return _units[i];
            }
            return null;
        }

        private static bool HasStatus(CombatUnitState u, string statusId)
        {
            for (int i = 0; i < u.statuses.Count; i++)
            {
                if (u.statuses[i].id == statusId) return true;
            }
            return false;
        }

        private static bool HasControlBlock(CombatUnitState u, string statusId) => HasStatus(u, statusId);

        private static double GetEffectiveAtk(CombatUnitState u)
        {
            double mult = 1.0;
            for (int i = 0; i < u.statuses.Count; i++)
            {
                if (u.statuses[i].id == "atk_up") mult += u.statuses[i].potency;
                else if (u.statuses[i].id == "atk_down") mult -= u.statuses[i].potency;
            }
            return Math.Max(1.0, u.atk * Math.Max(0.30, mult));
        }

        private static double GetEffectiveDef(CombatUnitState u)
        {
            double mult = 1.0;
            for (int i = 0; i < u.statuses.Count; i++)
            {
                if (u.statuses[i].id == "def_up") mult += u.statuses[i].potency;
                else if (u.statuses[i].id == "def_down") mult -= u.statuses[i].potency;
            }
            return Math.Max(0.0, u.def * Math.Max(0.20, mult));
        }

        private static double GetEffectiveSpeed(CombatUnitState u)
        {
            double mult = 1.0;
            for (int i = 0; i < u.statuses.Count; i++)
            {
                if (u.statuses[i].id == "spd_up") mult += u.statuses[i].potency;
                else if (u.statuses[i].id == "spd_down") mult -= u.statuses[i].potency;
            }
            return Math.Max(10.0, u.spd * Math.Max(0.40, mult));
        }

        private void EmitEvent(string type, string actorId, string targetId, string skillId, int value, bool isCrit, string statusId, string vfxPresetId, string note)
        {
            _seq++;
            _events.Add(new BattleEventRecord
            {
                seq = _seq,
                turn = _turn,
                type = type,
                actorId = actorId ?? "",
                targetId = targetId ?? "",
                skillId = skillId ?? "",
                value = value,
                isCrit = isCrit,
                statusId = statusId ?? "",
                vfxPresetId = vfxPresetId ?? "",
                note = note ?? ""
            });
        }
    }
}
